param([Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$BuildRoot)
$ErrorActionPreference='Stop';$ProjectRoot=[IO.Path]::GetFullPath($ProjectRoot);$BuildRoot=[IO.Path]::GetFullPath($BuildRoot);Add-Type -Path (Join-Path $PSScriptRoot PrivateDesktop.cs)
$root=Join-Path $ProjectRoot ('artifacts/circadian-tasks-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $root,(Join-Path $root tmp)|Out-Null;$env:TEMP=Join-Path $root tmp;$env:TMP=$env:TEMP
$env:HIBERNATION_SESSION_KEY='circadian-tasks-fixture';$service=$null;$provider=$null;$desktop=$null;$checks=0;$start=[DateTime]::UtcNow
function Check($Value,$Name){if(!$Value){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Await([scriptblock]$Probe,$Name,[int]$Seconds=25){$until=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$until){if($service-and$service.HasExited){throw 'fixture_backend_exited'};if(& $Probe){return};Start-Sleep -Milliseconds 80};throw "TIMEOUT $Name"}
function Api($Path,$Data=$null){$args=@{Uri=$script:origin+$Path;Headers=@{Authorization='Bearer circadian-tasks-fixture'};TimeoutSec=10};if($null-ne$Data){$args.Method='Post';$args.ContentType='application/json';$args.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 50 -Compress))};Invoke-RestMethod @args}
function Plan($Items,[int]$Delay=0){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Items|ForEach-Object {@{response=$_;delay_ms=$Delay}})}|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $root provider/plan.json) -Encoding utf8NoBOM}
function Call($Id,$Name,$Arguments){@{id=$Id;tool=$Name;args=$Arguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items)}}
function Silent{@{version=1;kind='silence';text=$null;calls=@()}}
function Requests{if(Test-Path -LiteralPath (Join-Path $root provider/requests.jsonl)){return @(Get-Content -LiteralPath (Join-Path $root provider/requests.jsonl)).Count};0}
function Plugin($Name,$Arguments){$null=Api '/api/plugin/test' @{tool=$Name;args=$Arguments};Await {$script:r=Api '/api/plugin/result';$script:r.state-in@('succeeded','failed')} $Name;if(!$script:r.result.ok){throw 'plugin_rejected'};return $script:r.result.result}
function Task{@((Api '/api/tasks').tasks)[0]}
try{
 $provider=Start-Process -FilePath (Join-Path $BuildRoot Hibernation_TestProvider.exe) -ArgumentList ('"'+$root+'/provider"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root provider.log) -RedirectStandardError (Join-Path $root provider-error.log);Await {Test-Path -LiteralPath (Join-Path $root provider/port)} provider;$fixture='http://127.0.0.1:'+(Get-Content -LiteralPath (Join-Path $root provider/port))
 $cfg=Get-Content -LiteralPath (Join-Path $ProjectRoot config/example.json) -Raw|ConvertFrom-Json -AsHashtable;$cfg.dataRoot=Join-Path $root data;$cfg.characterRoot=Join-Path $ProjectRoot character;$cfg.uiRoot=Join-Path $ProjectRoot ui;$cfg.pluginRoot=Join-Path $BuildRoot plugins;$cfg.frontend.startupAnimation=$false;$cfg.cognition=@{enabled=$true};$cfg.review=@{enabled=$false};$cfg.solitudeIntervalMs=604800000;$cfg.idleBeforeSolitudeMs=86400000;$cfg.maxStartsPerHour=1000
 $cfg.plugins=@{widget=@{enabled=$true;skin='asterlan';animationMode='sequence';roam=$false;autonomousMode=$true;autonomyIdleSeconds=600;autonomyRefillSeconds=600;reactionCacheEnabled=$false;showBubble=$false};rhythm=@{enabled=$true;automaticRest=$false;circadianEnabled=$true;idleBeforeRestSeconds=5}}
 $cfg.profiles=@($cfg.profiles[0],@{id='actor';label='Synthetic sleep task actor';enabled=$true;protocol='chat-completions';origin=$fixture;model='fixture-model';supportsJsonObject=$true});$config=Join-Path $root config.json;$ready=Join-Path $root ready.json;$cfg|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $config -Encoding utf8NoBOM
 $desktop=[PrivateDesktop]::new((Join-Path $BuildRoot hibernation-agent.exe),$config,$ready,$ProjectRoot);$service=$desktop.Child;Await {Test-Path -LiteralPath $ready} backend;$script:origin='http://127.0.0.1:'+((Get-Content -LiteralPath $ready -Raw|ConvertFrom-Json).port);$null=Api '/api/model' @{id='actor'}
 Plan @((Calls @((Call 'reminder' 'schedule.create' @{id='sleep-timer';topic='SYNTHETIC 稍后核对同一项资料';source_ids=@('${event_id}');after_ms=60000}),(Call 'task' 'task.start' @{goal='SYNTHETIC 分段核验资料';completion_criterion='实际完成核验后再提交结果';source_id='${event_id}'}))),(Silent))
 $null=Api '/api/message' @{request_id='sleep-task-source';text='SYNTHETIC 请分段核验资料，留一个稍后再检查的提醒；允许先休息。'};Await {!(Api '/api/chat').busy} initial;Check (@((Api '/api/tasks').tasks).Count-eq1-and(Api '/api/dashboard').remembered_schedules.active-eq1) 'actor creates a real task and one persistent reminder'
 Plan @((Calls @((Call 'checkpoint' 'task.checkpoint' @{id='${task_id}';expected_revision='${task_revision}';status='continue';summary='SYNTHETIC 目标已核对，下一段待继续';next_step='SYNTHETIC 继续核对下一部分';source_ids=@();wait_seconds=60}))),(Silent))
 Await {(Task).status-eq'ready'-and(Task).summary-like'SYNTHETIC*'} 'first actual task checkpoint';Check ((Task).steps-eq1-and(Task).failure_count-eq0) 'task checkpoint is accepted before resting'
 $m=(Get-Date).Hour*60+(Get-Date).Minute;$null=Plugin 'rhythm.configure' @{expected_revision=0;preferences=@{enabled=$true;start_minute=($m+1439)%1440;end_minute=($m+120)%1440;drag_wake_probability=0;message_wake_probability=0}}
 Await {(Api '/api/rhythm/status').phase-eq'sleeping'} sleep
 Check (!(Api '/api/activities/status').personal_pursuit.ready-and(Api '/api/activities/status').personal_pursuit.wait_reason-eq'sleeping') 'short own-time windows are not admitted while the body is asleep'
 $before=Requests;$deadline=[DateTime]::UtcNow.AddSeconds(67)
 while([DateTime]::UtcNow-lt$deadline){if((Api '/api/rhythm/status').phase-ne'sleeping'){throw 'sleep_interrupted'};Start-Sleep -Milliseconds 500}
 Check ((Requests)-eq$before) 'sleeping due work makes zero model requests'
 $task=Task;Check ($task.status-eq'ready'-and$task.failure_count-eq0-and$task.steps-eq1-and!$task.last_issue) 'sleep does not become missing-checkpoint failure or consume another task step'
 Check ((Api '/api/dashboard').remembered_schedules.active-eq1-and(Api '/api/dashboard').remembered_schedules.completed-eq0) 'sleep does not consume reminder as completed or missed'
 $job=@((Api '/api/state').jobs|Where-Object id -eq 'routine.sleep-timer')[0];$outcome=$job.result|ConvertFrom-Json;Check ($outcome.status-eq'deferred'-and$outcome.reason-eq'circadian_sleep'-and!$outcome.model_called) 'already armed timer retains an explicit no-model deferral receipt'
 Plan @((Silent)) 3000;$null=Api '/api/rhythm/wake' @{};Await {(Requests)-gt$before} 'wake resumes model admission';Check $true 'wake restores due work admission'
 $null=Api '/api/control' @{paused=$true};Await {!(Api '/api/chat').busy} 'pause resumed work';Check ((Api '/api/dashboard').paused) 'owner can stop resumed work without a fabricated completion'
 $null=Api '/api/shutdown' @{};Check ($service.WaitForExit(10000)-and$service.ExitCode-eq0) 'task fixture stops cleanly'
 @{completed=$true;checks=$checks;paid_model_calls=0;local_requests=(Requests);real_elapsed_seconds=([DateTime]::UtcNow-$start).TotalSeconds;resume_verification='admission_only_then_owner_pause';root=$root}|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $root acceptance.json) -Encoding utf8NoBOM;Write-Output "Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Api '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($desktop){$desktop.Dispose()};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
